function didWebToUrl(did) {
    const parts = did.split(':');
    if (parts[0] !== 'did' || parts[1] !== 'web') {
        throw new Error('unsupported DID method: ' + did);
    }
    const segments = parts.slice(2).map(decodeURIComponent);
    const domain = segments[0];
    const p = segments.slice(1);
    if (p.length === 0) return 'https://' + domain + '/.well-known/did.json';
    return 'https://' + domain + '/' + p.join('/') + '/did.json';
}

function dspError(code, detail) {
    return {
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' },
        payload: { '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}

const enforce = (env.get('DSP_IAM_ENFORCE') || 'enforce').toLowerCase();
if (enforce === 'off') {
    msg.identity = null;
    msg.iamRejected = false;
    msg._iamMode = 'off';
    return [null, null, msg];
}
msg._iamMode = enforce;

const authHeader = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const m = /^Bearer\s+(.+)$/i.exec(authHeader.trim());
if (!m) {
    const err = dspError('missing_authorization', 'Authorization: Bearer <vp+jwt> header is required');
    if (enforce === 'enforce') {
        Object.assign(msg, err);
        msg.identity = null;
        msg.iamRejected = true;
    } else {
        msg.identity = null;
        msg.iamRejected = false;
        node.warn('[iam-verify] warn-mode: ' + err.payload['dspace:reason'][0]);
    }
    return [null, null, msg];
}
const vpToken = m[1];

let vpPayload, vpHeader;
try {
    const parts = vpToken.split('.');
    vpHeader = JSON.parse(Buffer.from(parts[0], 'base64url').toString('utf8'));
    vpPayload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
} catch (e) {
    const err = dspError('invalid_signature', 'malformed VP token');
    if (enforce === 'enforce') { Object.assign(msg, err); msg.identity = null; msg.iamRejected = true; }
    else { msg.identity = null; msg.iamRejected = false; node.warn('[iam-verify] warn-mode: malformed VP'); }
    return [null, null, msg];
}

const holderDid = vpPayload.iss;
if (!holderDid || vpPayload.sub !== holderDid) {
    const err = dspError('holder_binding_failed', 'VP iss/sub mismatch');
    if (enforce === 'enforce') { Object.assign(msg, err); msg.identity = null; msg.iamRejected = true; }
    else { msg.identity = null; msg.iamRejected = false; node.warn('[iam-verify] warn-mode: VP iss/sub mismatch'); }
    return [null, null, msg];
}

let didUrl;
try {
    didUrl = didWebToUrl(holderDid || '');
} catch (e) {
    const err = dspError('key_mismatch', 'unsupported or missing holder DID');
    if (enforce === 'enforce') { Object.assign(msg, err); msg.identity = null; msg.iamRejected = true; }
    else { msg.identity = null; msg.iamRejected = false; node.warn('[iam-verify] warn-mode: ' + e.message); }
    return [null, null, msg];
}

msg._iamVp = { vpToken, vpPayload, vpHeader, holderDid, didUrl };

const cacheTtlMs = Number(env.get('DSP_IAM_DID_CACHE_TTL_SECONDS') || '300') * 1000;
const cache = global.get('iamDidCache') || new Map();
const cached = cache.get(didUrl);
const now = Date.now();
if (cached && (now - cached.fetchedAt) < cacheTtlMs) {
    msg._iamVp.didDoc = cached.doc;
    return [msg, null, null];
}
msg.url = didUrl;
return [null, msg, null];

function dspError(code, detail) {
    return {
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' },
        payload: { '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}

function reject(msg, code, detail) {
    const err = dspError(code, detail);
    if (msg._iamMode === 'enforce') {
        Object.assign(msg, err);
        msg.identity = null;
        msg.iamRejected = true;
    } else {
        msg.identity = null;
        msg.iamRejected = false;
        node.warn('[iam-verify] warn-mode: ' + code + ' — ' + detail);
    }
    return msg;
}

// `jose` here is in scope from this node's own `libs` declaration below
// (Node-RED's functionExternalModules injects it as a bound variable,
// exactly like the existing `crypto` variable is in-scope in dsp-tx-create
// via its own libs array) — it is NOT read from global context.

(async () => {
    const vp = msg._iamVp;
    if (!vp) {
        node.error('[iam-verify] missing _iamVp context — programmer error, check wiring');
        node.send(reject(msg, 'invalid_signature', 'internal verifier error'));
        return;
    }

    // This response came either from the cache-hit branch (msg._iamVp.didDoc
    // already set by dsp-iam-prep) or from the http-request node (msg.payload
    // is the fetched did.json body).
    const didDoc = vp.didDoc || msg.payload;
    if (!didDoc || !Array.isArray(didDoc.verificationMethod)) {
        node.send(reject(msg, 'key_mismatch', 'did.json unresolvable or malformed: ' + vp.didUrl));
        return;
    }
    if (!vp.didDoc) {
        const cache = global.get('iamDidCache') || new Map();
        cache.set(vp.didUrl, { doc: didDoc, fetchedAt: Date.now() });
        global.set('iamDidCache', cache);
    }

    function findJwk(doc, kid) {
        const vm = doc.verificationMethod.find(v => v.id === kid || v.id === (kid || '').split('#').pop());
        if (!vm || !vm.publicKeyJwk) throw new Error('verificationMethod not found for kid=' + kid);
        return vm.publicKeyJwk;
    }

    let vpKey;
    try {
        vpKey = await jose.importJWK(findJwk(didDoc, vp.vpHeader.kid), vp.vpHeader.alg);
    } catch (err) {
        node.send(reject(msg, 'key_mismatch', 'could not resolve VP signer key: ' + err.message));
        return;
    }

    try {
        const audience = env.get('DSP_VP_AUDIENCE') || 'did:web:fap-iotai.facis.cloud';
        await jose.jwtVerify(vp.vpToken, vpKey, { audience });
    } catch (err) {
        if (err && err.code === 'ERR_JWT_EXPIRED') { node.send(reject(msg, 'token_expired', 'VP expired')); return; }
        if (err && err.code === 'ERR_JWT_CLAIM_VALIDATION_FAILED' && err.claim === 'aud') {
            node.send(reject(msg, 'invalid_audience', 'VP aud mismatch')); return;
        }
        node.send(reject(msg, 'invalid_signature', 'VP signature verification failed: ' + err.message));
        return;
    }

    // vp.holderDid !== vp.vpPayload.sub (holder_binding_failed) is already
    // gated in dsp-iam-prep, before key resolution/signature verify, to
    // match iam-verify.spec.js's priority order — unreachable here.
    if (!vp.vpPayload.jti) {
        node.send(reject(msg, 'invalid_signature', 'VP missing jti')); return;
    }

    const jtiTtlMs = Number(env.get('DSP_IAM_JTI_TTL_SECONDS') || '300') * 1000;
    const jtiCache = global.get('iamJtiCache') || new Map();
    const now = Date.now();
    for (const [k, exp] of jtiCache) { if (exp <= now) jtiCache.delete(k); }
    if (jtiCache.has(vp.vpPayload.jti)) {
        node.send(reject(msg, 'replay_detected', 'VP jti already used: ' + vp.vpPayload.jti)); return;
    }
    jtiCache.set(vp.vpPayload.jti, now + jtiTtlMs);
    global.set('iamJtiCache', jtiCache);

    const vcTokens = (vp.vpPayload.vp && vp.vpPayload.vp.verifiableCredential) || [];
    if (!vcTokens.length) { node.send(reject(msg, 'invalid_credential', 'VP has no verifiableCredential')); return; }
    const vcToken = vcTokens[0];

    let vcHeader, vcPayload;
    try {
        const parts = vcToken.split('.');
        vcHeader = JSON.parse(Buffer.from(parts[0], 'base64url').toString('utf8'));
        vcPayload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
    } catch (e) {
        node.send(reject(msg, 'invalid_credential', 'malformed inner VC')); return;
    }

    const trustedIssuers = (env.get('DSP_TRUSTED_ISSUERS') || '').split(',').map(s => s.trim()).filter(Boolean);
    if (!trustedIssuers.includes(vcPayload.iss)) {
        node.send(reject(msg, 'untrusted_issuer', 'VC issuer not in allowlist: ' + vcPayload.iss)); return;
    }

    const subject = (vcPayload.vc && vcPayload.vc.credentialSubject) || {};
    if (subject.id !== vp.holderDid) {
        node.send(reject(msg, 'holder_binding_failed', 'VC credentialSubject.id != VP holder')); return;
    }

    // VC issuer key: resolve its did.json too (cached the same way), and
    // importJWK the kid — both are "resolve" failures per iam-verify.spec.js
    // and map to key_mismatch, kept in a try/catch separate from jwtVerify.
    let vcKey;
    try {
        const vcDidUrl = didWebToUrlSafe(vcPayload.iss);
        let vcDoc;
        const cache = global.get('iamDidCache') || new Map();
        const cached = cache.get(vcDidUrl);
        if (cached && (Date.now() - cached.fetchedAt) < Number(env.get('DSP_IAM_DID_CACHE_TTL_SECONDS') || '300') * 1000) {
            vcDoc = cached.doc;
        } else {
            const resp = await fetch(vcDidUrl); // eslint-disable-line no-undef
            vcDoc = await resp.json();
            cache.set(vcDidUrl, { doc: vcDoc, fetchedAt: Date.now() });
            global.set('iamDidCache', cache);
        }
        vcKey = await jose.importJWK(findJwk(vcDoc, vcHeader.kid), vcHeader.alg);
    } catch (err) {
        node.send(reject(msg, 'key_mismatch', 'could not resolve VC issuer key: ' + err.message));
        return;
    }

    try {
        await jose.jwtVerify(vcToken, vcKey);
    } catch (err) {
        if (err && err.code === 'ERR_JWT_EXPIRED') { node.send(reject(msg, 'token_expired', 'VC expired')); return; }
        node.send(reject(msg, 'invalid_credential', 'VC signature verification failed: ' + err.message));
        return;
    }

    function didWebToUrlSafe(did) {
        const parts = (did || '').split(':');
        if (parts[0] !== 'did' || parts[1] !== 'web') throw new Error('unsupported DID method: ' + did);
        const segs = parts.slice(2).map(decodeURIComponent);
        return segs.length === 1 ? 'https://' + segs[0] + '/.well-known/did.json'
                                 : 'https://' + segs[0] + '/' + segs.slice(1).join('/') + '/did.json';
    }

    msg.identity = {
        did: vp.holderDid,
        roles: subject.roles || [],
        credentialId: vcPayload.jti || vcPayload.id || null,
        verifiedAt: new Date().toISOString()
    };
    msg.iamRejected = false;
    delete msg._iamVp;
    node.send(msg);
})();
return;
